import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'github-issues-fetch',
  description: 'Fetches a bounded, incremental window of GitHub repository issues.',
  inputs: {
    cursor: { type: 'json', description: 'Last successfully synced GitHub updated_at value.' },
    config: { type: 'json', description: 'Repository owner, name, and optional API base URL.', required: true },
  },
  outputs: {
    records: { type: 'array', description: 'GitHub issues ready for connector normalization.', itemType: 'object' },
    cursor: { type: 'string', description: 'Newest updated_at value processed.', nullable: true },
    rateLimited: { type: 'boolean', description: 'True when GitHub throttled the pass; the engine backs off and retries from this cursor.', nullable: true },
    partial: { type: 'boolean', description: 'True when more pages remained after the per-pass page budget.', nullable: true },
  },
  requires: ['network', 'credential:$credential'],
} as const);

type Config = { owner?: unknown; repository?: unknown; apiBaseUrl?: unknown };
type Issue = Record<string, unknown> & { updated_at?: unknown; pull_request?: unknown };
const input = gezel.input as { cursor?: unknown; config?: Config };
const config = input.config ?? {};
const owner = typeof config.owner === 'string' ? config.owner.trim() : '';
const repository = typeof config.repository === 'string' ? config.repository.trim() : '';
if (!owner || !repository) throw new Error('GitHub owner and repository are required.');

const apiBaseUrl =
  typeof config.apiBaseUrl === 'string' && config.apiBaseUrl.trim()
    ? config.apiBaseUrl.trim().replace(/\/+$/, '')
    : 'https://api.github.com';
let apiOrigin: string;
try {
  const parsed = new URL(apiBaseUrl);
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') throw new Error('bad protocol');
  apiOrigin = parsed.origin;
} catch {
  throw new Error('GitHub API base URL must be an absolute HTTP or HTTPS URL.');
}

const params = new URLSearchParams({
  state: 'all',
  sort: 'updated',
  direction: typeof input.cursor === 'string' ? 'asc' : 'desc',
  per_page: '100',
});
if (typeof input.cursor === 'string' && input.cursor) params.set('since', input.cursor);
let nextUrl =
  apiBaseUrl + '/repos/' + encodeURIComponent(owner) + '/' + encodeURIComponent(repository) + '/issues?' + params;
let nextCursor = typeof input.cursor === 'string' ? input.cursor : null;
const records: Issue[] = [];
let rateLimited = false;

function nextPage(link: string | undefined): string | null {
  if (!link) return null;
  for (const part of link.split(',')) {
    const match = part.match(/<([^>]+)>;\s*rel="next"/);
    if (match?.[1]) return match[1];
  }
  return null;
}

function isThrottle(status: number, headers: Record<string, string | undefined>): boolean {
  if (status === 429) return true;
  return status === 403 && (headers['x-ratelimit-remaining'] === '0' || Boolean(headers['retry-after']));
}

for (let page = 0; page < 5 && nextUrl; page++) {
  const target = new URL(nextUrl);
  if (target.origin !== apiOrigin) throw new Error('GitHub pagination changed origin; refusing to forward the token.');
  const headers = {
    Accept: 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
    'User-Agent': 'Gezel-GitHub-Issues-Connector',
  };
  let response;
  try {
    response = await gezel.http.authed(target.toString(), {
      credential: '$credential',
      headers,
    });
  } catch (error) {
    if ((error as { code?: string }).code !== 'CREDENTIAL_MISSING') throw error;
    response = await gezel.http.request(target.toString(), { headers });
  }
  if (isThrottle(response.status, response.headers)) {
    // Emit what this pass already collected with the cursor those records
    // reached, and flag the throttle instead of throwing: a throw voids the
    // batch and re-fetches the same window next tick, which is exactly how
    // rate-limited APIs get hammered. The engine persists the cursor only
    // after a clean write and applies its jittered backoff to the binding.
    rateLimited = true;
    break;
  }
  if (!response.ok) {
    throw new Error('GitHub issues request failed (' + response.status + '): ' + response.body.slice(0, 240));
  }
  const pageItems = JSON.parse(response.body) as unknown;
  if (!Array.isArray(pageItems)) throw new Error('GitHub returned a non-array issues response.');
  for (const raw of pageItems) {
    if (!raw || typeof raw !== 'object') continue;
    const issue = raw as Issue;
    const updatedAt = typeof issue.updated_at === 'string' ? issue.updated_at : '';
    if (updatedAt && (!nextCursor || updatedAt > nextCursor)) nextCursor = updatedAt;
    if (issue.pull_request) continue;
    const labels = Array.isArray(issue.labels)
      ? issue.labels
          .map((label) =>
            typeof label === 'string'
              ? label
              : label && typeof label === 'object'
                ? String((label as Record<string, unknown>).name ?? '')
                : '',
          )
          .filter(Boolean)
      : [];
    const assignees = Array.isArray(issue.assignees)
      ? issue.assignees
          .map((person) =>
            person && typeof person === 'object'
              ? String((person as Record<string, unknown>).login ?? '')
              : '',
          )
          .filter(Boolean)
      : [];
    records.push({
      ...issue,
      gezel_repository: owner + '/' + repository,
      gezel_labels: labels,
      gezel_assignees: assignees,
    });
  }
  const candidate = nextPage(response.headers.link);
  nextUrl = candidate && new URL(candidate).origin === apiOrigin ? candidate : '';
}

const cursorOut = records.length > 0 ? nextCursor : typeof input.cursor === 'string' ? input.cursor : null;
gezel.output({
  records,
  cursor: rateLimited ? cursorOut : nextCursor,
  ...(rateLimited ? { rateLimited: true } : {}),
  ...(nextUrl && !rateLimited ? { partial: true } : {}),
});

import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'http-json-rows-fetch',
  description: 'Fetches a bounded page of rows from a JSON or NDJSON HTTP endpoint.',
  inputs: {
    cursor: { type: 'json', description: 'Opaque continuation value from the previous pass.' },
    config: { type: 'json', description: 'Endpoint URL, item path, and paging fields.', required: true },
  },
  outputs: {
    records: { type: 'array', description: 'Rows for the observation table.', itemType: 'object' },
    cursor: { type: 'string', description: 'Continuation value for the next pass.', nullable: true },
    rateLimited: { type: 'boolean', description: 'True when the source throttled the pass.', nullable: true },
    partial: { type: 'boolean', description: 'True when more pages remained after the page budget.', nullable: true },
  },
  requires: ['network', 'credential:$credential'],
} as const);

type Config = {
  url?: unknown;
  itemsPath?: unknown;
  format?: unknown;
  timeField?: unknown;
  sinceParam?: unknown;
  pageParam?: unknown;
  nextPagePath?: unknown;
  maxPages?: unknown;
};

const input = gezel.input as { cursor?: unknown; config?: Config };
const config = input.config ?? {};

const rawUrl = typeof config.url === 'string' ? config.url.trim() : '';
if (!rawUrl) throw new Error('An endpoint URL is required.');
let origin: string;
try {
  const parsed = new URL(rawUrl);
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') throw new Error('bad protocol');
  origin = parsed.origin;
} catch {
  throw new Error('The endpoint URL must be an absolute HTTP or HTTPS URL.');
}

const itemsPath = typeof config.itemsPath === 'string' ? config.itemsPath.trim() : '';
const format = config.format === 'ndjson' ? 'ndjson' : 'json';
const timeField = typeof config.timeField === 'string' ? config.timeField.trim() : '';
const sinceParam = typeof config.sinceParam === 'string' ? config.sinceParam.trim() : '';
const nextPagePath = typeof config.nextPagePath === 'string' ? config.nextPagePath.trim() : '';
const maxPages = Number.isFinite(Number(config.maxPages))
  ? Math.max(1, Math.min(Number(config.maxPages), 20))
  : 5;

/** Walk a dotted `a.b.c` path (with or without a leading `$.`). */
function pick(value: unknown, path: string): unknown {
  if (!path) return value;
  let current = value;
  for (const key of path.replace(/^\$\.?/, '').split('.')) {
    if (!key) continue;
    if (current === null || typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

function rowsFrom(body: string): Record<string, unknown>[] {
  if (format === 'ndjson') {
    const out: Record<string, unknown>[] = [];
    for (const line of body.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      const parsed = JSON.parse(trimmed) as unknown;
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        out.push(parsed as Record<string, unknown>);
      }
    }
    return out;
  }
  const parsed = JSON.parse(body) as unknown;
  const items = itemsPath ? pick(parsed, itemsPath) : parsed;
  if (!Array.isArray(items)) {
    throw new Error(
      itemsPath
        ? 'The item path did not resolve to a list. Check `itemsPath` against the response shape.'
        : 'The endpoint did not return a list. Set `itemsPath` to where the rows live in the response.',
    );
  }
  return items.filter(
    (item): item is Record<string, unknown> =>
      Boolean(item) && typeof item === 'object' && !Array.isArray(item),
  );
}

function isThrottle(status: number, headers: Record<string, string | undefined>): boolean {
  if (status === 429) return true;
  return status === 503 && Boolean(headers['retry-after']);
}

const priorCursor = typeof input.cursor === 'string' ? input.cursor : '';
let nextUrl = rawUrl;
if (sinceParam && priorCursor) {
  const target = new URL(rawUrl);
  target.searchParams.set(sinceParam, priorCursor);
  nextUrl = target.toString();
}

const records: Record<string, unknown>[] = [];
let newestSeen = priorCursor;
let rateLimited = false;
let more = false;

for (let page = 0; page < maxPages && nextUrl; page++) {
  const target = new URL(nextUrl);
  // Never forward the credential across an origin change — a redirect or a
  // hostile `nextPagePath` would otherwise leak it to a third party.
  if (target.origin !== origin) {
    throw new Error('Pagination changed origin; refusing to forward the credential.');
  }
  const headers = { Accept: format === 'ndjson' ? 'application/x-ndjson' : 'application/json' };
  let response;
  try {
    response = await gezel.http.authed(target.toString(), { credential: '$credential', headers });
  } catch (error) {
    if ((error as { code?: string }).code !== 'CREDENTIAL_MISSING') throw error;
    response = await gezel.http.request(target.toString(), { headers });
  }
  if (isThrottle(response.status, response.headers)) {
    // Emit what this pass collected and flag the throttle rather than
    // throwing: a throw voids the batch and re-fetches the same window next
    // tick, which is how a rate-limited API gets hammered.
    rateLimited = true;
    break;
  }
  if (!response.ok) {
    throw new Error('Row fetch failed (' + response.status + '): ' + response.body.slice(0, 240));
  }

  const pageRows = rowsFrom(response.body);
  for (const row of pageRows) {
    records.push(row);
    if (timeField) {
      const value = pick(row, timeField);
      if (typeof value === 'string' && (!newestSeen || value > newestSeen)) newestSeen = value;
    }
  }

  let candidate = '';
  if (nextPagePath && format === 'json') {
    const link = pick(JSON.parse(response.body) as unknown, nextPagePath);
    if (typeof link === 'string' && link) candidate = link;
  }
  if (candidate && new URL(candidate, origin).origin === origin) {
    nextUrl = new URL(candidate, origin).toString();
    more = page + 1 >= maxPages;
  } else {
    nextUrl = '';
  }
}

gezel.output({
  records,
  cursor: newestSeen || null,
  ...(rateLimited ? { rateLimited: true } : {}),
  ...(more && !rateLimited ? { partial: true } : {}),
});
